-- Table constraint: PRIMARY KEY NONCLUSTERED HASH
CREATE TABLE dbo.SessionState
(
    SessionId VARCHAR(50) NOT NULL,
    Payload NVARCHAR(MAX) NOT NULL,
    CONSTRAINT PK_SessionState PRIMARY KEY NONCLUSTERED HASH (SessionId)
        WITH (BUCKET_COUNT = 16384)
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);
GO

-- Table constraint: UNIQUE NONCLUSTERED HASH
CREATE TABLE dbo.SessionStateUnique
(
    SessionId VARCHAR(50) NOT NULL,
    Payload NVARCHAR(MAX) NOT NULL,
    CONSTRAINT UQ_SessionState UNIQUE NONCLUSTERED HASH (SessionId)
        WITH (BUCKET_COUNT = 16384)
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);
GO

-- Table index element: NONCLUSTERED HASH
CREATE TABLE dbo.TableIndexHash
(
    SessionId VARCHAR(50) NOT NULL,
    Payload NVARCHAR(MAX) NOT NULL,
    INDEX IX_SessionId NONCLUSTERED HASH (SessionId) WITH (BUCKET_COUNT = 16384)
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);
GO

-- Column constraint: PRIMARY KEY NONCLUSTERED HASH
CREATE TABLE dbo.ColumnConstraintHash
(
    SessionId VARCHAR(50) NOT NULL PRIMARY KEY NONCLUSTERED HASH WITH (BUCKET_COUNT = 16384),
    Payload NVARCHAR(MAX) NOT NULL
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);
GO

-- Column index: NONCLUSTERED HASH
CREATE TABLE dbo.ColumnIndexHash
(
    SessionId VARCHAR(50) NOT NULL INDEX IX_ColumnHash NONCLUSTERED HASH WITH (BUCKET_COUNT = 16384),
    Payload NVARCHAR(MAX) NOT NULL
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);
GO
